mapper.update:
UPDATE s_points_order
SET status = #{canceledStatus},
    cancel_time = #{cancelTime},
    cancel_reason = #{cancelReason}
WHERE id = #{id}
  AND deleted = 0
  AND status = #{pendingStatus}

UPDATE s_points_order
SET status = #{shippedStatus},
    delivery_provider_code = #{providerCode},
    tracking_no = #{trackingNo},
    ship_time = #{shipTime}
WHERE id = #{id}
  AND deleted = 0
  AND status = #{pendingStatus}
  AND fulfillment_type = #{logisticsFulfillmentType}

UPDATE s_points_order
SET status = #{completedStatus},
    complete_time = #{completeTime},
    fulfillment_remark = #{fulfillmentRemark}
WHERE id = #{id}
  AND deleted = 0
  AND status = #{pendingStatus}

UPDATE s_points_order
SET status = #{completedStatus},
    complete_time = #{completeTime}
WHERE id = #{id}
  AND deleted = 0
  AND status = #{shippedStatus}

mapper.select:
SELECT COALESCE(SUM(quantity), 0)
FROM s_points_order
WHERE deleted = 0
  AND member_id = #{memberId}
  AND spu_id = #{spuId}
  AND status != #{canceledStatus}
